export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug || p.id === slug);
}

export function getRelatedBlogPosts(
  currentSlug: string,
  category?: string,
  limit = 3
): BlogPost[] {
  const otherPosts = BLOG_POSTS.filter(
    (p) => p.slug !== currentSlug && p.id !== currentSlug
  );

  if (category) {
    const sameCategory = otherPosts.filter((p) => p.category === category);
    if (sameCategory.length >= limit) {
      return sameCategory.slice(0, limit);
    }
    const differentCategory = otherPosts.filter((p) => p.category !== category);
    return [...sameCategory, ...differentCategory].slice(0, limit);
  }

  return otherPosts.slice(0, limit);
}
